import{_ as n}from"./chunks/image12.BRgDBKom.js";import{_ as a,o as i,c as r,am as t,j as o}from"./chunks/framework.CenUaW7a.js";const s="/projects/AiMechaM1/en/advanced-kit/assets/video1.D8UScK47.mp4",l="/projects/AiMechaM1/en/advanced-kit/assets/image2.CB0BuT3f.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image3.CwbMhzTd.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image4.DQH--XM8.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image5.DttdbPW5.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image7.u2l3xOBx.png",x=JSON.parse('{"title":"3.30 Lesson 30: Deep Visual Perception and Control Integration","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.30 Lesson 30 Deep Visual Perception and Control Integration.md","filePath":"docs/3. Course materials/3.30 Lesson 30 Deep Visual Perception and Control Integration.md"}'),h={name:"docs/3. Course materials/3.30 Lesson 30 Deep Visual Perception and Control Integration.md"};function u(m,e,f,v,b,y){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="_3-30-lesson-30-deep-visual-perception-and-control-integration" tabindex="-1">3.30 Lesson 30: Deep Visual Perception and Control Integration <a class="header-anchor" href="#_3-30-lesson-30-deep-visual-perception-and-control-integration" aria-label="Permalink to &quot;3.30 Lesson 30: Deep Visual Perception and Control Integration&quot;">​</a></h1><h2 id="_3-30-1-lesson-introduction" tabindex="-1">3.30.1 Lesson Introduction <a class="header-anchor" href="#_3-30-1-lesson-introduction" aria-label="Permalink to &quot;3.30.1 Lesson Introduction&quot;">​</a></h2><p>Focusing on advanced scenario applications of large vision models, this lesson establishes a closed loop from &quot;visual comprehension → action control&quot;. Starting from the scenario of an intelligent logistics robot reading floor numbers to reach designated shelves, the curriculum contrasts traditional card recognition, which requires extensive training data, with zero-shot recognition powered by large vision models. Standard methods often fail when encountering handwritten digits, whereas large vision models recognize arbitrary numbered road signs through semantic associations. Practical exercises feature two progressive tasks: recognizing cards with voice broadcasting to verify zero-shot performance, and linking card recognition to Mecanum-wheel car left turns or specific travel distances. Exploring industrial scenarios such as logistics sorting illustrates how large models free robots from specialized fiducial markers, enabling interaction via universal symbols and completing the leap from visual comprehension to physical control.</p><h2 id="_3-30-2-learning-objectives" tabindex="-1">3.30.2 Learning Objectives <a class="header-anchor" href="#_3-30-2-learning-objectives" aria-label="Permalink to &quot;3.30.2 Learning Objectives&quot;">​</a></h2><ol><li><p>Understand the technical principles and limitations of classic card recognition. Grasp the core mechanisms of zero-shot recognition in large vision models, and comprehend the closed-loop recognition → control system architecture.</p></li><li><p>Implement vision-model-based recognition for numbered cards and road signs. Develop programs for voice announcement of recognition results, and integrate card recognition with the motion control of a Mecanum-wheeled robot.</p></li><li><p>Develop a control mindset where visual perception drives physical action. Build a conceptual understanding of zero-shot learning, and enhance engineering design skills spanning from scenario requirements to system implementation.</p></li><li><p>Relate the learned concepts to real-world applications such as smart logistics sorting, warehouse AGV navigation, autonomous driving road sign recognition, and indoor service robot navigation, and appreciate the revolutionary value of large vision models in the robotics industry.</p></li></ol><h2 id="_3-30-3-preparation" tabindex="-1">3.30.3 Preparation <a class="header-anchor" href="#_3-30-3-preparation" aria-label="Permalink to &quot;3.30.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li>AiMecha M1 Mecanum-Wheel Car Advanced Kit</li><li>Type-C data cable</li><li>Computer × 1</li><li>Remote controller</li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Core Concept Comparison</strong>:</p><ul><li><p><strong>Traditional Card Recognition</strong>: Requires collecting massive datasets of numbered cards and road signs in advance to train a classification model. Such models only recognize fixed, pre-trained classes and frequently fail when encountering handwritten digits, color variations, or tilted angles. Three major limitations include reliance on extensive annotated data, restriction to preset categories, and inability to comprehend underlying card semantics.</p></li><li><p><strong>Large Vision Model Recognition</strong>: Pre-trained on massive image-text pair datasets to establish associations between visual features and semantic concepts. Inputting a card image enables direct zero-shot output of natural language descriptions such as &quot;This is a card with the number 3&quot; or &quot;This is a left-turn arrow sign&quot;, while even comprehending implied instructional meanings. Three main advantages include out-of-the-box readiness without training, recognition of arbitrary numbered road signs or handwritten digits, and natural language outputs that can be directly parsed into control commands.</p></li></ul><p><strong>Application Scenario Description</strong>:</p><ul><li><p><strong>Smart Logistics Sorting</strong>: Warehouse automated guided vehicles use vision to read floor numbers and autonomously drive to corresponding shelves for item pickup without relying on magnetic strips or QR codes.</p></li><li><p><strong>Indoor Visual Navigation</strong>: Service robots recognize directional arrows and room numbers along hallways to navigate autonomously to target destinations.</p></li><li><p><strong>Autonomous Driving Road Sign Recognition</strong>: Autonomous vehicles identify traffic signs and lane markings in real time to assist driving decisions.</p></li><li><p><strong>Flexible Production Lines</strong>: Industrial robots read numbered labels on workpieces to automatically switch process parameters, adapting seamlessly to high-mix, low-volume manufacturing.</p></li></ul><p><strong>Wiring Guidelines</strong>:</p><ul><li><p>Connect the K230 screen module to <strong>port A</strong> of the controller via UART serial communication.</p></li><li><p>Connect the camera module to the dedicated camera port on the K230 screen module.</p></li></ul><p><strong>Programming Framework Key Points</strong>:</p><ul><li><p>Initialization Workflow: Wait 6 seconds → play the B5 prompt tone → initialize port A → configure Wi-Fi settings → load default MCP configuration → switch to online large model mode → initialize the robotic arm → play the B6 readiness tone.</p></li><li><p>Main Loop Structure: Start detection execution → repeatedly update data → check for recognition results → store results in AIresult → evaluate the motor speed branch → evaluate the movement distance branch → send ok feedback.</p></li><li><p>Key Variable: Use AIresult to temporarily cache recognition results and maintain data consistency.</p></li></ul><h2 id="_3-30-4-practical-implementation" tabindex="-1">3.30.4 Practical Implementation <a class="header-anchor" href="#_3-30-4-practical-implementation" aria-label="Permalink to &quot;3.30.4 Practical Implementation&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This project builds a card recognition and motion control system driven by a large vision model, centered around a closed loop that translates visual semantics into motion commands. The K230 module captures images of numbered cards and road signs, while the cloud-based large model performs zero-shot semantic comprehension to output natural language descriptions. The decision-making layer parses rules defined via voice commands and invokes MCP tools upon recognizing target cards to generate motor speeds, movement directions, and travel distances. The execution layer independently drives the four Mecanum wheels for omnidirectional movement or precise displacement before stopping. Forming a complete pipeline from visual capture → cloud comprehension → rule matching → tool invocation → motion execution, the system supports arbitrary card categories without prior training, demonstrating the disruptive advantages of general AI in robot perception and serving as a miniature prototype of intelligent AGV navigation.</p>',21),o("p",null,[o("video",{controls:"",playsinline:"",preload:"metadata",src:s})],-1),t('<p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Motor control</td><td style="text-align:center;"><img loading="lazy" height="46" width="569" src="'+l+'" class="common_img" style="width:100px;aspect-ratio:569 / 46;"></td><td style="text-align:left;">Independently sets the rotational speeds of the four Mecanum wheel motors to achieve omnidirectional motion control.</td></tr><tr><td style="text-align:center;">Movement control</td><td style="text-align:center;"><img loading="lazy" height="57" width="548" src="'+c+'" class="common_img" style="width:100px;aspect-ratio:548 / 57;"></td><td style="text-align:left;">Precisely controls the car to move at a specified speed and direction for a target distance before stopping.</td></tr><tr><td style="text-align:center;">Tool evaluation</td><td style="text-align:center;"><img loading="lazy" height="102" width="643" src="'+d+'" class="common_img" style="width:100px;aspect-ratio:643 / 102;"></td><td style="text-align:left;">Evaluates whether the large model has invoked the corresponding motion control tool.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Recognizing Cards and Broadcasting Content</strong></p><ul><li><p>Initialization settings: Upon startup, wait 6 seconds and play note B5 for a 1/8 beat as the startup prompt tone. Initialize port A, configure the Wi-Fi SSID and password, load the default MCP configuration, set the operating mode to online large model, initialize the linkage robotic arm, and play note B6 for a 1/8 beat as the readiness prompt tone.</p></li><li><p>Voice trigger: Speak the wake word <code>Hello Hiwonder</code>, followed by the command &quot;recognize the card and broadcast its content&quot;.</p></li><li><p>Visual recognition: The large model triggers the camera to capture a frame, analyzes the card content using the large vision model, and generates a natural language description such as &quot;this is a card with the number 7&quot; or &quot;detected a right-turn arrow sign&quot;.</p></li><li><p>Voice broadcast: Text-to-speech synthesis converts the recognition result into audio and automatically broadcasts the card content aloud.</p></li><li><p>Testing and verification: Sequentially present numbered cards from 0 to 9 and road sign cards including turn left, turn right, go straight, and stop to observe recognition accuracy.</p></li><li><p>Advanced testing: Test the robustness of the large vision model using handwritten digits, tilted cards, and varying lighting conditions.</p></li></ul><img loading="lazy" height="369" width="591" src="'+p+'" class="common_img" style="width:400px;aspect-ratio:591 / 369;"><p><strong>Task 2: Recognizing Cards to Control Mecanum-Wheel Car Actions</strong></p><ul><li><p>Program framework: Uses the exact same initialization sequence and main loop structure as Task 1.</p></li><li><p>Result retrieval: If <code>Does result exist?</code> returns true, store the retrieved recognition result in the <code>AIresult</code> variable.</p></li><li><p>Motor speed branch: If AIresult contains the default MCP tool name for motor speed, set the front-left, rear-left, front-right, and rear-right wheel speeds of the Mecanum-wheel car to the respective motor speed parameters extracted from AIresult, and send a response result with dictionary key <code>result</code> and value <code>ok</code>.</p></li><li><p>Movement distance branch: If AIresult contains the default MCP tool name for movement distance, command the Mecanum-wheel car to translate at the rotational speed in rpm, toward the directional angle in degrees, and for the distance in centimeters extracted from AIresult, then send the response result <code>ok</code>.</p></li><li><p>Voice command example: &quot;Recognize the card ahead, and if it is a left-turn card, turn left in place for one second&quot;.</p></li><li><p>Execution outcome: Placing a left-turn card in front of the car causes it to automatically turn left in place upon recognition; replacing it with a right-turn card triggers a right turn, and presenting a stop card brings the car to a halt.</p></li></ul><img loading="lazy" height="321" width="1474" src="'+g+'" class="common_img" style="width:1000px;aspect-ratio:1474 / 321;"><p><strong>Program Design Key Points</strong></p><ul><li><p>Variable caching mechanism: Store recognition results uniformly in AIresult so all tool evaluation branches read from the same variable, ensuring data consistency.</p></li><li><p>Parallel multi-tool structure: Place the motor speed and movement distance branches in parallel, allowing the large model to select the appropriate control method based on the voice command.</p></li><li><p>Natural language rules: Define control rules dynamically via spoken commands rather than hard-coded logic; changing the spoken rule immediately alters the response behavior with high flexibility.</p></li><li><p>Zero-shot adaptation: Eliminate the need to train separate models for each card type—any novel card containing letters, symbols, or text can be recognized directly, showcasing the generalization strength of large models.</p></li></ul><p><strong>Typical Control Phrases</strong></p><ul><li><p><code>Recognize the numbered card ahead, and move forward by the corresponding number of centimeters</code></p></li><li><p><code>Turn left upon seeing a left-turn arrow, and turn right upon seeing a right-turn arrow</code></p></li><li><p><code>Stop immediately upon detecting a stop sign</code></p></li><li><p><code>Recognize the number on the card, and drive faster for larger numbers</code></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/Visual Perception Joint Control</a>.</strong></p></div></li></ul><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and plug the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button on the top toolbar of the software and select the COM port corresponding to CH340 from the dropdown list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to compile and download the program to the mecha controller.</p></li></ul><img loading="lazy" height="508" width="960" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-30-5-expansion-and-advancement" tabindex="-1">3.30.5 Expansion and Advancement <a class="header-anchor" href="#_3-30-5-expansion-and-advancement" aria-label="Permalink to &quot;3.30.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Intelligent Warehouse Sorting Robot</strong></p><p>Set up a simulated warehouse environment by placing floor markers for shelves 1, 2, and 3 alongside directional arrows. Design an intelligent sorting program where the car departs from the starting area, navigates autonomously by following floor directional arrows, identifies shelf numbers upon reaching the storage zone, and drives to the target shelf based on voice commands such as &quot;Deliver the cargo to Shelf 3&quot;. Simulate a real-world logistics AGV workflow to explore how large vision models enable robots to navigate using universal symbols and master the technical principles of flexible logistics.</p><p><strong>Expansion Project 2: Custom Card Instruction System</strong></p><p>Design a custom &quot;card instruction&quot; set by creating various functional cards, such as moving forward, moving backward, spinning in place, illuminating red lights, and sounding the buzzer, where each card corresponds to a specific robot action. Verify whether the large vision model can accurately recognize custom-made cards and execute the matching actions. Test the system with hand-drawn cards in varying colors and sizes to explore the recognition boundaries and generalization capabilities of large vision models, creating a fully customized visual command interaction system.</p><h2 id="_3-30-6-q-a" tabindex="-1">3.30.6 Q&amp;A <a class="header-anchor" href="#_3-30-6-q-a" aria-label="Permalink to &quot;3.30.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: To control the car using an unseen, hand-drawn right-turn symbol card based on the methods covered in this lesson, which of the following approaches is most appropriate?</strong></p><p>A. Shine a flashlight on the card. B. Invoke the zero-shot recognition capability of the large vision model. C. Measure the distance using the ultrasonic sensor. D. Capture hundreds of photos of right-turn arrows in different styles to train a dedicated model first.</p><p><strong>Answer: B</strong></p><p><strong>Q2: In the card recognition and motion control program, the recognition result retrieved from the online large model is stored in a variable such as <code>AI result</code>. Why not evaluate the retrieval block directly inside the conditional loop, and what is the purpose of caching it in a variable?</strong></p><p><strong>Answer</strong>: Evaluating the retrieval block directly inside the loop <strong>repeatedly fetches results</strong>, causing program lag or slow responsiveness; caching the output in a variable <strong>retrieves the result once for reuse across multiple branches</strong>, making program execution faster and more stable.</p><h2 id="_3-30-7-technical-support-and-discussion" tabindex="-1">3.30.7 Technical Support and Discussion <a class="header-anchor" href="#_3-30-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.30.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',29)])])}const k=a(h,[["render",u]]);export{x as __pageData,k as default};
